const Stripe = require\('stripe'\);
const stripe = new Stripe\('$STRIPE_SECRET_KEY'\);
\(async \(\) => {
  const endpoints = await stripe.webhookEndpoints.list\({ limit: 10 }\);
  const ep = endpoints.data[0];

  // Update to include all the events our webhook handler needs
  const updated = await stripe.webhookEndpoints.update\(ep.id, {
    enabled_events: [
      'checkout.session.completed',
      'checkout.session.expired',
      'charge.refunded',
      'account.updated',
      'payment_intent.succeeded',
      'payment_intent.created',
    ],
  }\);

  console.log\('Updated endpoint:', updated.url\);
  console.log\('New events:', updated.enabled_events.join\(', '\)\);
}\)\(\);
